    if(action==='delete-object'){if(!confirm('Удалить объект из мобильного прототипа?'))return;const d=sheet;const property=({server:'servers',profile:'profiles',route:'routes',subscription:'subscriptions'})[d.objectKind];state[property]=state[property].filter(i=>i.id!==d.id);if(d.objectKind==='subscription')state.servers=state.servers.filter(s=>s.subscriptionId!==d.id);for(const p of state.profiles){p.configIds=(p.configIds||[]).filter(id=>state.servers.some(s=>s.id===id));if(p.routeId===d.id)p.routeId='';if(p.subscriptionId===d.id)p.subscriptionId='';}if(!selected()){state.selected='';connection='off';}persist();log('Удалён объект: '+({server:'конфигурация',profile:'профиль',route:'маршрут',subscription:'подписка'})[d.objectKind]+'.');back();return;}
