  root.addEventListener('input',event=>{const el=event.target;if(el.dataset.search==='servers'){search=el.value;render();return;}if(el.dataset.search==='logs'){logSearch=el.value;render();return;}if(el.dataset.field){if(sheet?.kind==='import'){const d=state.drafts[sheet.tab];d[el.dataset.field==='import-name'?'name':'value']=el.value;sheet.error='';persist();}else if(sheet?.kind==='object-import'){sheet.value=el.value;sheet.error='';}else if(editor){editor[el.dataset.field]=el.value;delete editor.error;}}});
  root.addEventListener('change',async event=>{const el=event.target;if(el.dataset.field&&editor){editor[el.dataset.field]=el.value;if(el.dataset.field==='format')render();}if(el.dataset.config&&editor){const ids=new Set(editor.configIds||[]);el.checked?ids.add(el.dataset.config):ids.delete(el.dataset.config);editor.configIds=[...ids];}if(el.dataset.file){const target=sheet,file=el.files?.[0];if(!file)return;try{if(file.size>5000000)throw Error('Файл слишком большой.');const raw=await file.text();if(sheet!==target)return;if(target.kind==='import'){state.drafts.file.value=raw;state.drafts.file.name ||= file.name.replace(/\.(conf|txt)$/i,'');persist();}else target.value=raw;render();}catch(error){if(sheet===target){target.error=error.message;render();}}}});
